<?php
namespace App\Http\Controllers;
use App\Services\Agent\FarastEditorAgent;use Illuminate\Http\Request;use RuntimeException;
class EditorAgentController extends Controller{
 public function plan(Request $request,FarastEditorAgent $agent){$d=$request->validate(['document_id'=>['required','integer'],'prompt'=>['required','string','max:4000'],'selection'=>['nullable','array'],'organization_id'=>['nullable','integer'],'budget'=>['nullable','array']]);try{return response()->json($agent->plan($request->user(),(int)$d['document_id'],$d['prompt'],$d));}catch(RuntimeException $e){$map=['agent_permission_denied'=>403,'agent_document_forbidden'=>403,'agent_selection_required'=>422,'agent_stale_revision'=>409,'agent_intent_not_supported'=>422,'agent_tool_not_available'=>422,'agent_tool_version_unavailable'=>422,'quota_exhausted'=>402,'insufficient_credit'=>402,'not_entitled'=>403];return response()->json(['ok'=>false,'error_code'=>$e->getMessage(),'message'=>$e->getMessage()],$map[$e->getMessage()]??422);}}
 public function approve(Request $request,FarastEditorAgent $agent,string $task){$d=$request->validate(['approved'=>['required','boolean']]);try{return response()->json($agent->approve($request->user(),$task,(bool)$d['approved']));}catch(RuntimeException $e){return response()->json(['ok'=>false,'error_code'=>$e->getMessage(),'message'=>$e->getMessage()],422);}}
 public function commit(Request $request,FarastEditorAgent $agent,string $task){$d=$request->validate(['base_revision'=>['required','integer','min:0'],'result_revision'=>['required','integer','min:0'],'transactions'=>['required','integer','min:0','max:10'],'changed_blocks'=>['required','integer','min:0','max:100'],'changed_characters'=>['required','integer','min:0','max:100000'],'command_ids'=>['nullable','array']]);try{return response()->json($agent->commit($request->user(),$task,$d));}catch(RuntimeException $e){return response()->json(['ok'=>false,'error_code'=>$e->getMessage(),'message'=>$e->getMessage()],$e->getMessage()==='agent_stale_revision'?409:422);}}
}